---------------2023-05-03
----- table id,val,desce

create table motif_voyage (
    id varchar(100) constraint motif_voyage_pk primary key,
    val varchar(200),
    desce varchar(200)
);


create sequence seqmotif_voyage
      minvalue 1
      maxvalue 999999999999
      start with 1
      increment by 1
      cache 20;
      
      

CREATE OR REPLACE FUNCTION getseqmotif_voyage
   RETURN NUMBER
IS
   retour   NUMBER;
BEGIN
   SELECT seqmotif_voyage.NEXTVAL INTO retour FROM DUAL;

   RETURN retour;
END; 


create table categorie_professionnel (
    id varchar(100) constraint categorie_professionnel_pk primary key,
    val varchar(250),
    desce varchar(250)
);


create sequence seqcategorie_professionnel
      minvalue 1
      maxvalue 999999999999
      start with 1
      increment by 1
      cache 20;
      
      

CREATE OR REPLACE FUNCTION getseqcategorie_professionnel
   RETURN NUMBER
IS
   retour   NUMBER;
BEGIN
   SELECT seqcategorie_professionnel.NEXTVAL INTO retour FROM DUAL;

   RETURN retour;
END; 

-------------- indemnite_mission

create table indemnite_mission (
    id varchar(100) constraint indemnite_mission_pk primary key,
    idcategorieprofessionnel varchar(100) constraint indemnite_categorie_fk references categorie_professionnel(id),
    fraishebergement number(10,2),
    fraisrestauration  number(10,2),
    fraisdeplacement   number(10,2),
    fraisforfaitaire   number(10,2),
    daty date,
    etat int
);


create sequence seqindemnite_mission
      minvalue 1
      maxvalue 999999999999
      start with 1
      increment by 1
      cache 20;
      
      

CREATE OR REPLACE FUNCTION getseqindemnite_mission
   RETURN NUMBER
IS
   retour   NUMBER;
BEGIN
   SELECT seqindemnite_mission.NEXTVAL INTO retour FROM DUAL;

   RETURN retour;
END; 


------------ vue indemnite_mission_lib
create view indemnite_mission_lib as 
select 
im.*,
cp.VAL AS idcategorieprofessionnellib,
CASE 
	WHEN im.etat = 1
	THEN 'Crée'
	WHEN im.etat = 11
	THEN 'Validée'
END
AS etatlib
from INDEMNITE_MISSION im 
LEFT JOIN CATEGORIE_PROFESSIONNEL cp ON cp.ID = im.IDCATEGORIEPROFESSIONNEL ;

---------------- “ordre_mission”


create table ordre_mission (
    id varchar(100) constraint ordre_mission_pk primary key,
    idindemnitemission varchar(100) constraint ordre_indemnite_fk references indemnite_mission(id),
    idtiers varchar(100) constraint ordre_tiers_fk references tiers(id),
    idmotifvoyage varchar(100) constraint ordre_motif_voyage_fk references motif_voyage(id),
    lieudeplacement varchar(100),
    duree number(10,2),
    datedepart date,
    numOM varchar(100),
    estForfaitaire int,
    etat int
);


create sequence seqordre_mission
      minvalue 1
      maxvalue 999999999999
      start with 1
      increment by 1
      cache 20;
      
      

CREATE OR REPLACE FUNCTION getseqordre_mission
   RETURN NUMBER
IS
   retour   NUMBER;
BEGIN
   SELECT seqordre_mission.NEXTVAL INTO retour FROM DUAL;

   RETURN retour;
END; 
			




ALTER TABLE INFOPERSONNELGLOBAL ADD idtiers varchar(100) CONSTRAINT info_tiers_fk REFERENCES TIERS(id);

------------------ 2023-05-05

create OR REPLACE view ordre_mission_lib as 
select 
om.id ,
om.IDINDEMNITEMISSION,
cp.val AS IDINDEMNITEMISSIONlib,
om.idtiers,
om.IDMOTIFVOYAGE,
mv.VAL AS IDMOTIFVOYAGElib,
om.LIEUDEPLACEMENT,
om.DUREE,
om.DATEDEPART,
om.NUMOM,
om.ESTFORFAITAIRE,
CASE 
	WHEN om.ESTFORFAITAIRE = 1
	THEN 'oui'
	WHEN om.ESTFORFAITAIRE = -1
	THEN 'non'
END AS ESTFORFAITAIRElib,
om.ETAT,
CASE 
	WHEN om.etat = 1
	THEN 'crée'
	WHEN om.etat = 11
	THEN 'validée'
END AS etatlib,
i.NOM ,
i.PRENOM ,
i.POSTE AS fonction,
i.NUMERO_MATRICULE AS matricule
from ORDRE_MISSION om 
LEFT JOIN INFOPERSONNELGLOBAL i ON i.IDTIERS = om.IDTIERS 
LEFT JOIN INDEMNITE_MISSION im ON im.ID = om.IDINDEMNITEMISSION
LEFT JOIN CATEGORIE_PROFESSIONNEL cp ON cp.id = im.IDCATEGORIEPROFESSIONNEL 
LEFT JOIN MOTIF_VOYAGE mv ON mv.ID = om.IDMOTIFVOYAGE ;




			
	CREATE OR  replace VIEW INDEMNITE_MISSION_LIB_ligne as			         
        SELECT 
        i.id,
        i.IDCATEGORIEPROFESSIONNEL,
        i.FRAISHEBERGEMENT AS montant,
         i.DATY ,
        i.ETAT ,
        i.IDCATEGORIEPROFESSIONNELLIB ,
        i.ETATLIB ,
        'FRAIS D HEBERGEMENT' AS typeindemnite
        FROM  INDEMNITE_MISSION_LIB i
        union
        SELECT 
        i.id,
        i.IDCATEGORIEPROFESSIONNEL,
        i.FRAISRESTAURATION AS montant,
         i.DATY ,
        i.ETAT ,
        i.IDCATEGORIEPROFESSIONNELLIB ,
        i.ETATLIB ,
        'FRAIS DE RESTAURATION' AS typeindemnite
        FROM  INDEMNITE_MISSION_LIB i
        union
        SELECT 
        i.id,
        i.IDCATEGORIEPROFESSIONNEL,
        i.FRAISDEPLACEMENT AS montant, 
         i.DATY ,
        i.ETAT ,
        i.IDCATEGORIEPROFESSIONNELLIB ,
        i.ETATLIB ,
        'FRAIS DE DEPLACEMENT' AS typeindemnite
        FROM  INDEMNITE_MISSION_LIB i
        ;
       
       
       CREATE OR  replace VIEW INDEMNITE_MISSION_LIB_forf as			         
        SELECT 
        i.id,
        i.IDCATEGORIEPROFESSIONNEL,
        i.FRAISFORFAITAIRE  AS montant,
         i.DATY ,
        i.ETAT ,
        i.IDCATEGORIEPROFESSIONNELLIB ,
        i.ETATLIB ,
        'FRAIS FORFAITAIRE' AS typeindemnite
        FROM  INDEMNITE_MISSION_LIB i;
       
       
       CREATE OR REPLACE view ordre_missiom_indemnite
       AS SELECT oml.id,oml.IDINDEMNITEMISSION,oml.IDTIERS,o.typeindemnite,o.montant  FROM ORDRE_MISSION_LIB oml
       LEFT JOIN INDEMNITE_MISSION_LIB_ligne o ON oml.IDINDEMNITEMISSION =o.id;
        
            CREATE OR REPLACE view ordre_missiom_forfaitaire
       AS SELECT oml.id,oml.IDINDEMNITEMISSION,oml.IDTIERS,o.typeindemnite,o.montant  FROM ORDRE_MISSION_LIB oml
       LEFT JOIN INDEMNITE_MISSION_LIB_forf o ON oml.IDINDEMNITEMISSION =o.id;
      
