  CREATE OR REPLACE  VIEW FACTFOURN_MSUM_LIB_MODIF_ORDRE (ID, DATY,DATEFACTURE, DATEREGUL, TIERS, DESIGNATION, TYPE, TVA, REMARQUE, IDUSER, DATE_ECHEANCE, ETAT, IDPREVISION, MONTANT, MONTANTTVA, MONTANTAVOIR, MONTANTTTC, MONTANTPAYE, MONTANTRESTE, TIERSLIB, CONTACT, ADRESSE, ESCALE, TYPELIB, IDCATEGORIE, CATEGORIELIB, IDPROVISION, IDPROVISIONLIB, ESTDDPMICTSL, DEVISEMERE, CODEPRESTATION, CODEPRESTATIONLIB, CODE, ESTMICTSL, CODEPROVISION, ETATLIB, MONTANTTTCVRAI, IDBL, CODE_ETABLISSEMENT, CODE_ETABLISSEMENTLIB, NUMEROOP, PROJET, PROJETLIB, NUMFACT, NATURE, NATURELIB, IDBC, EXERCICE, IDENGAGEMENT, IDENGAGEMENTLIB, MONTANTHTSANSREMISE) AS 
  SELECT m.ID,
       m.DATY,
       m.DATEFACTURE ,
	   m.DATEREGUL,
       m.TIERS,
       m.DESIGNATION,
       m.TYPE,
       m.TVA,
       '--' || m.remarque AS remarque,
       m.IDUSER,
       m.DATE_ECHEANCE,
       m.ETAT,
       m.idprevision,
       CAST(m.MONTANT AS NUMBER(32, 2)) as MONTANT ,
       CAST(M.MONTANTTVA AS NUMBER(32, 2)) as MONTANTTVA,
       CAST(M.MONTANTAVOIR AS NUMBER(32, 2))as MONTANTAVOIR,
       CAST(M.MONTANTTTC AS NUMBER(32, 2))as MONTANTTTC,
       CAST(NVL(pf.montant, 0) AS NUMBER(32, 2)) AS montantpaye,
       CAST(M.MONTANTTTC - NVL(pf.montant, 0) AS NUMBER(32, 2)) AS montantreste,
       fup.NOM  AS tierslib,
       fup.CONTACT,
       fup.ADRESSE,
       M.ESCALE,
       TYPELIB,
       m.IDCATEGORIE,
       m.CATEGORIELIB,
       m.IDPROVISION,
       m.IDPROVISIONLIB,
       m.ESTDDPMICTSL,
       m.devisemere,
       m.codePrestation,
       m.codePrestationlib,
       m.CODE,
       m.ESTMICTSL,
       codeprovision,
       case
           when m.etat = 1 then 'CREE'
           when m.etat >= 11 then 'VISE'
           else '' end                           as etatlib,
       cast(MONTANTTTCVRAI as number(32,2)) as MONTANTTTCVRAI,
       m.IDBL,
       m.CODE_ETABLISSEMENT,
       m.CODE_ETABLISSEMENTLIB,
       m.NUMEROOP,
       m.PROJET,
       m.PROJETLIB,
       m.NUMFACT,
       m.NATURE,
       m.naturelib,
       m.IDBC,
       m.exercice,
       IDENGAGEMENT,
       idengagementlib ,
       cast(m.MONTANTHTSANSREMISE AS NUMBER(30,2)) AS MONTANTHTSANSREMISE
FROM FACTFOURN_MSUM m
         LEFT JOIN FOURNISSEUR_UNION_PERSONNEL fup ON fup.ID = m.tiers
         LEFT JOIN paiementfacturefsum pf ON pf.idfact = m.id
		 
	;
	
	CREATE OR REPLACE  VIEW SITUATIONLCDEPENSEGRP (DIRECTION, PROJET, COMPTE, MONTANT, ENGAGEER, FACTURE, PAYE, ARECOUVRIR, RESTEBUDGET, POURCENGAGE, POURCPAYE, RESTEAPRESENGMT, IDPROJET, IDCODEETABLISSEMENT, ANNEE) AS 
  select l.direction,
       l.projet,
       l.COMPTEFULL                                                     as compte,
       cast(sum(l.montant)  as number(30,3))                                                 as montant,
       cast(nvl(n.montant, 0) + nvl(nt.MONTANT, 0) - nvl(gr.MONTANT, 0) + nvl(bc.montant, 0) +
            nvl(bp.montant, 0) as NUMBER(30, 3))                        as engageer,
       cast(nvl(fd.facture, 0) as NUMBER(30, 3))                        as facture,
       cast(nvl(fd.PAYE, 0) as number(30, 3))                           as PAYE,
       cast(nvl(fd.facture, 0) - nvl(fd.PAYE, 0) as NUMBER(30, 3))      as arecouvrir,
       cast(sum(l.montant) - nvl(fd.facture, 0) as NUMBER(30, 3))       as restebudget,
       cast(nvl(fd.facture, 0) / sum(l.MONTANT) * 100 as NUMBER(30, 3)) as pourcEngage,
       cast(nvl(fd.PAYE, 0) / sum(l.MONTANT) * 100 as number(30, 3))    as pourcPaye,
       cast(sum(l.montant) - (nvl(n.montant, 0) + nvl(nt.MONTANT, 0) - nvl(gr.MONTANT, 0) +
                              nvl(bc.montant, 0)) as NUMBER(30, 3))     as resteApresEngmt,
       l.idprojet,
       l.iddirection                                                    AS idcodeEtablissement,
       l.ANNEE
from SITUATIONLCDEPENSE_FULL l
         LEFT JOIN (SELECT cast(nvl(sum(MONTANT), 0) as NUMBER(30, 3))     as facture,
                           cast(nvl(sum(MONTANTPAYE), 0) as number(30, 3)) as PAYE,
                           substr(mf.COMPTE, 1, 6)                         as comptefull,
                           mf.ANNEE

                    FROM DETAILSFACTUREFOURNISSEUR_paye mf
                    WHERE 1 < 2 and (typeengagement!='ED' or TYPEENGAGEMENT is null)
                          --  and mf.daty >= '01/01/2022'
                    group by substr(mf.COMPTE, 1, 6), mf.ANNEE) fd on l.COMPTEFULL = fd.comptefull
         left join (select substr(COMPTE, 1, 6) as compte, sum(MONTANT) as montant, annee
                    from DETAILSFACTUREFOURNISSEUR_paye
                    where IDENGAGEMENT is null
                          --   and daty >= '01/01/2022'
                    group by substr(COMPTE, 1, 6), annee) n on n.compte = l.COMPTEfull
         left join (SELECT sum(montant) AS montant, PROJET, codeetablissement, projetlib, codeetablissementlib
                    FROM engagementlibv ev
                    WHERE 1 < 2
                          --    and ev.daty >= '01/01/2022'
                    GROUP BY PROJET, codeetablissement, projetlib, codeetablissementlib) nt
                   on nt.projet = l.idprojet AND nt.codeetablissement = l.iddirection
         left join (select en.ID, sum(li.MONTANT) as MONTANT, DATY as DATYENGAGEMENT, PROJET, codeetablissement
                    from LIBERER li
                             left join ENGAGEMENT en on en.ID = li.IDENGAGEMENT
                    where li.ETAT >= 11
                          -- and en.daty >= '01/01/2022'
                    group by en.ID, DATY, PROJET, codeetablissement) gr
                   on nt.PROJET = gr.PROJET and nt.CODEETABLISSEMENT = gr.CODEETABLISSEMENT
         left join (select comptebdg, sum(MONTANTNONFACTURE) as montant
                    from SITUATION_BC_SANSENG bc
                    WHERE 1 < 2
                          --  and bc.daty >= '01/01/2022'
                    group by comptebdg) bc on bc.comptebdg = l.comptefull
         left join (select sum(MONTANTRESTE) as montant, COMPTEFULL as compte
                    from ETATBPVRAI bp
                    WHERE 1 < 2
                          --  and bp.daty >= '01/01/2022'
                    group by COMPTEFULL) bp on bp.compte = l.COMPTEFULL
where 1 < 2
GROUP BY l.DIRECTION, l.projet, n.montant, nt.MONTANT, gr.MONTANT, fd.facture, fd.PAYE,
         l.direction, l.projet, l.COMPTEFULL, l.idprojet, l.iddirection, bc.montant, bp.montant, l.idprojet,
         l.iddirection, l.ANNEE;

	
        CREATE OR REPLACE  VIEW SITUATIONLCDEPENSEGRP_TEMP (DIRECTION, PROJET, DIRECTIONPROJET, COMPTE, MONTANT, N_MONTANT, NON_MONTANT, NT_MONTANT, GR_MONTANT, BC_MONTANT, BP_MONTANT, ENGAGEER, FACTURE, PAYE, ARECOUVRIR, RESTEBUDGET, POURCENGAGE, POURCPAYE, RESTEAPRESENGMT, IDPROJET, IDCODEETABLISSEMENT, ANNEE) AS 
  select l.direction,
       l.projet,
       l.directionprojet,
       l.COMPTEFULL                                                     as compte,
       cast(sum(l.montant )as NUMBER(30, 3))                                                   as montant
        ,
       cast(nvl(n.montant, 0)as NUMBER(30, 3))                                               as N_MONTANT
        ,
       cast(-1 * nvl(non.montant, 0) as NUMBER(30, 3))                                         as NON_Montant
        ,
       cast(nvl(nt.MONTANT, 0)as NUMBER(30, 3))                                               as NT_Montant
        ,
       cast(-1 * nvl(gr.MONTANT, 0) as NUMBER(30, 3))                                          as GR_MONTANT
        ,
       cast(nvl(bc.montant, 0)as NUMBER(30, 3))                                               as BC_MONTANT
        ,
       cast(nvl(bp.montant, 0)as NUMBER(30, 3))                                               as BP_MONTANT
        ,
       --cast(nvl(n.montant, 0) +
       cast(nvl(nt.MONTANT, 0)as NUMBER(30, 3)) /*- nvl(non.montant, 0)*/
           /*- nvl(gr.MONTANT, 0) + nvl(bc.montant, 0) + nvl(bp.montant, 0) as NUMBER(30, 3)) */
                                                                        as engageer,
       cast(nvl(fd.facture, 0) as NUMBER(30, 3))                        as facture,
       cast(nvl(fd.PAYE, 0) as number(30, 3))                           as PAYE,
       cast(nvl(fd.facture, 0) - nvl(fd.PAYE, 0) as NUMBER(30, 3))      as arecouvrir,
       cast(sum(l.montant) - nvl(fd.facture, 0) as NUMBER(30, 3))       as restebudget,
       cast(nvl(fd.facture, 0) / sum(l.MONTANT) * 100 as NUMBER(30, 3)) as pourcEngage,
       cast(nvl(fd.PAYE, 0) / sum(l.MONTANT) * 100 as number(30, 3))    as pourcPaye,
       /*cast(sum(l.montant) -
            (nvl(n.montant, 0) - nvl(non.montant, 0) + nvl(nt.MONTANT, 0) - nvl(gr.MONTANT, 0) + nvl(bc.montant, 0) +
             nvl(bp.montant, 0)) as NUMBER(30, 3))*/
       CAST(cast(sum(l.montant) as Number(30,3)) - cast(nvl(nt.MONTANT, 0)as NUMBER(30, 3))as NUMBER(30, 3))    as resteApresEngmt,
       l.idprojet,
       l.iddirection                                                    AS idcodeEtablissement,
       l.ANNEE
from SITUATIONLCDEPENSE_FULL l
         LEFT JOIN (SELECT cast(nvl(sum(MONTANT), 0) as NUMBER(30, 3))     as facture,
                           cast(nvl(sum(MONTANTPAYE), 0) as number(30, 3)) as PAYE,
                           substr(mf.COMPTE, 1, 6)                         as comptefull,
                           mf.ANNEE
                    FROM DETAILSFACTUREFOURNISSEUR_paye mf
                    WHERE 1 < 2
                      --and (typeengagement != 'ED' or TYPEENGAGEMENT is null)
                      --  and mf.daty >= '01/01/2022'
                    group by substr(mf.COMPTE, 1, 6), mf.ANNEE) fd
                   on l.COMPTEFULL = fd.comptefull and l.annee = fd.annee
         left join (select substr(COMPTE, 1, 6) as compte, sum(MONTANT) as montant, annee
                    from DETAILSFACTUREFOURNISSEUR_paye
                    where IDENGAGEMENT is null
                          --   and daty >= '01/01/2022'
                    group by substr(COMPTE, 1, 6), annee) n on n.compte = l.COMPTEfull and n.annee = l.annee
         left join (SELECT sum(montant) AS montant, PROJET, codeetablissement, projetlib, codeetablissementlib, annee
                    FROM engagementlibv ev
                    WHERE 1 < 2
                          --    and ev.daty >= '01/01/2022'
                    GROUP BY PROJET, codeetablissement, projetlib, codeetablissementlib, annee) nt
                   on nt.projet = l.idprojet AND nt.codeetablissement = l.iddirection and nt.annee = l.annee
         left join (select substr(COMPTE, 1, 6) as compte, sum(MONTANT) as montant, annee
                    from DETAILSFACTUREFOURNISSEUR_paye
                    where IDENGAGEMENT is not null
                          --and daty >= to_date('01/01/2023', 'dd/mm/yyyy')
                    group by substr(COMPTE, 1, 6), annee) non on non.compte = l.COMPTEfull and non.annee = l.annee
         left join (select en.ID
                         , sum(li.MONTANT) as MONTANT
                         --, DATY as DATYENGAGEMENT
                         , PROJET
                         , codeetablissement
                         , annee
                    from LIBERER li
                             left join ENGAGEMENT en on en.ID = li.IDENGAGEMENT
                    where li.ETAT >= 11
                          -- and en.daty >= '01/01/2022'
                    group by en.ID
                           --, DATY
                           , PROJET, codeetablissement, annee) gr
                   on nt.PROJET = gr.PROJET and nt.CODEETABLISSEMENT = gr.CODEETABLISSEMENT and gr.annee = l.annee
         left join (select comptebdg, sum(MONTANTNONFACTURE) as montant, annee
                    from SITUATION_BC_SANSENG bc
                    WHERE 1 < 2
                          --  and bc.daty >= '01/01/2022'
                    group by comptebdg, annee) bc on bc.comptebdg = l.comptefull and bc.annee = l.annee
         left join (select sum(MONTANTRESTE) as montant, COMPTEFULL as compte, annee
                    from ETATBPVRAI bp
                    WHERE 1 < 2
                          --  and bp.daty >= '01/01/2022'
                    group by COMPTEFULL, annee) bp on bp.compte = l.COMPTEFULL and bp.annee = l.annee
where 1 < 2
GROUP BY l.DIRECTION, l.projet, n.montant, non.montant, nt.MONTANT, gr.MONTANT, fd.facture, fd.PAYE,
         l.direction, l.projet, l.COMPTEFULL, l.idprojet, l.iddirection, bc.montant, bp.montant, l.idprojet,
         l.iddirection, l.ANNEE, l.directionprojet

;


		 


